#!/usr/bin/env python3
"""Serialize individually read and literature-searched cote-29 claims.
The judgments below are authored records, not classifications inferred by code.
"""
from pathlib import Path
import json,csv,datetime
root=Path(__file__).resolve().parents[1]
items=[x for x in json.loads((root/'items.json').read_text()) if int(x['id'].split('-')[-1])<=260];by={x['id']:x for x in items}
claims=[];search=[]
def C(n,ii,statement,status,cl,fate,refs,date='',comp='',confidence='high',batches=()):
    ii=[f'SA12-{i}'for i in ii];its=[by[i]for i in ii]
    rec=dict(id=f'CL-SA12-{n:03}',items=ii,cote='29',scans=sorted({s for i in its for s in i['scans']}),lines='; '.join(dict.fromkeys(i['lines'] for i in its)),his_statement=' | '.join(dict.fromkeys(i['his_words'] for i in its if i['his_words'])) or 'Statement paraphrased in the associated item; see its exact transcription locator.',statement=statement,status_on_pages=status,computation=comp or 'No numerical calculation underlies this assertion. The textual and literature comparisons are recorded separately from proof checks.',**{'class':cl},fate=fate,fate_date=date or 'Publication/circulation dates are distinguished in the references; no date is inferred for this undated leaf.',present_status='As of 2026-11-19: '+fate,refs=refs,confidence=confidence)
    claims.append(rec);search.append({'claim_id':rec['id'],'search_batches':['web_root_%03d.json'%b for b in batches],'opened_reference_keys':refs,'scope_note':fate})

C(201,[205,212],'For the stated regular formal neighborhood with normal-crossing boundary, the tame-inertia extension is classified at finite invertible coefficient level by the Kummer Chern classes of the normal/boundary line bundles, with the base action and preceding pi_2 boundary retained.','proof sketched','A','SGA1 XIII5.3.0 supplies the strict-local normal-crossing Kummer calculation; SGA7 I provides the tame-inertia action. The finite-level Cech identification is independently checked in reviews/29a/independent_checks.md §7. The precise semiglobal formal-cover category and sign convention are not identified merely by these later references. This is an established local construction, with those reconstruction limits.',['SA12_SGA1','SA12_SGA7I','SA12_Stacks03PK'],'SGA1 seminar1960–61, publication1971; SGA7I publication1972.',batches=(3,7,12,20))
C(202,[206],'Earlier-run diagnostic: arithmetic tame inertia need not be central; F_4((u))/F_2((t)), t=u^3, has group C_3 semidirect C_2 with inversion action. This is not presented as an authorial counterexample.','not an authorial claim; diagnostic of the reconstruction','E','The cyclotomic action is explicit in SGA7 I§1. The finite example satisfies ramification index3 prime to residue characteristic2 and residue degree2. It refutes arithmetic centrality without trivializing the action, not a geometric centrality statement.',['SA12_SGA7I'],comp='Independent proof §1 and exact_checks.json: C3 conjugation verified.',batches=(12,19))
C(203,[207],'The implication pi_2(base)=0 ⇒ the indicated extension splits needs a vanishing extension class in H^2(pi_1(base),I), beyond vanishing of the homotopy boundary.','stated without proof; overstrong reconstruction is false','C','The Heisenberg extension over a torus, and the degree-one line-bundle complement over a complex elliptic curve, exhibit the remaining H^2 obstruction. The latter geometric construction is checked in review29a §7. The source phrase trivial remains ambiguous; no universal formal-neighborhood statement is assigned to it without that definition.',['SA12_SGA1','SA12_SGA7I'],comp='Upper-unitriangular matrix commutator in exact_checks.json; the computation diagnoses a logical implication, not unspecified formal hypotheses.',batches=(3,7,12))
C(204,[208],'For a P^1 boundary with normal-bundle degree d, the tame inertia predicted by the homotopy sequence is coker(d:T^(p-prime)→T^(p-prime)). It is cyclic of order |d| with its p-part removed when d≠0; for d=0 it is the whole Tate module.','stated without proof; finite cyclic formula needs d≠0','A','The normal-crossing tame computation and finite Kummer classes fit SGA1 XIII5.3.0. The zero-degree exception follows directly from the displayed cokernel. The notation mu_n requires scan verification if no nonzero-degree hypothesis is present.',['SA12_SGA1','SA12_Stacks03PK'],comp='Exact prime-to-p cokernel examples plus universal proof in independent_checks.md §1.',batches=(3,20))
C(205,[209],'Compute the indicated tame higher-homotopy groups of Spec Z minus a prescribed finite set of primes, with the omitted primes, coefficient primes and real-place convention fixed.','open on the pages','C','Schmidt2007 Theorem6.2 gives a pro-p K(pi,1) after suitable enlargement of S under its stated hypotheses; it does not calculate the full tame pi_2 for every original S. Schmidt2000 treats tame abelian finiteness and normal-crossing local models. The exact all-prime question, with the page\'s incomplete conventions, is not settled by either source; the residual formulation must be fixed before claiming modern openness.',['SA12_Schmidt2007','SA12_Schmidt2000'],'Schmidt2000 arXiv May2000; Schmidt2007 publication2007.',confidence='medium',batches=(3,7,20))
C(206,[210],'An apparent blanket assertion that the arithmetic tame fundamental group is abelian or finite is reading-dependent; the abelianization formula and infinity-place convention must be separated.','stated without proof; negative word/scope unresolved','F','The polynomial x^3−4x+1 has totally real S3 splitting field and squarefree discriminant229, hence only tame finite ramification. It excludes a universal abelian interpretation even with real places unramified. No general finiteness claim follows from this example, and no uncertain word is selected. Searches through arithmetic tame/K(pi,1) literature did not identify the precise handwritten quantifier.',['SA12_Schmidt2007','SA12_Schmidt2000'],comp='Rational-root and discriminant calculation in exact_checks.json; all arithmetic hypotheses checked in independent_checks.md §1.',confidence='medium',batches=(7,20))
C(207,[211],'The henselian-pair normal-crossing construction should produce the semiglobal tame group from commuting branch inertia factors, subject to the indicated connectedness and invertibility hypotheses.','proof sketched','A','SGA1 XIII5.3.0 gives the strict-local Kummer theorem and Schmidt2000 §1.2 restates it. This establishes the local input. Pairwise commutation of branch factors is weaker than centrality in the arithmetic group. The semiglobal gluing step must retain its chosen category and cannot be inferred solely from the local theorem.',['SA12_SGA1','SA12_Schmidt2000'],confidence='medium',batches=(3,20))
C(208,[213,214],'The deleted commutation formulation and the proposed extension to formal schemes or ringed topoi are programmes; normality of two inertia subgroups alone does not make them commute.','corrected by himself later: formulation deleted on scan103; reason not documented','C','The finite Kummer and classifying-topos mechanisms were developed in SGA1/SGA4, but no theorem for every formal scheme or ringed topos with these unspecified hypotheses is asserted. The two normal cyclic subgroups of Q8 supply an independent logical counterexample to normality implying commutation.',['SA12_SGA1','SA12_SGA4I'],comp='Q8 multiplication table and commutator in exact_checks.json.',confidence='medium',batches=(3,12,19))
C(209,[215],'For F,G∈GL(V), dim V finite, q>1 and FGF^−1=G^q, some positive power of G is unipotent.','proof sketched in a deleted passage; cancellation is not a refutation','A','The eigenvalue-permutation proof is valid and independently re-proved here. SGA7 I1.1 presents the arithmetic quasi-unipotence application and cites the Serre–Tate Appendix for its proof. The source\'s draft lemma6.5 is not final SGA7 I6.5, which concerns abelian reduction.',['SA12_SGA7I','SA12_SerreTate1968'],'Serre–Tate publication1968; redacted SGA7I1972.',comp='Universal finite-spectrum proof in independent_checks.md §2. Invertibility is checked explicitly; a diagonal zero eigenvalue is a counterexample if it is dropped.',batches=(12,19,21))
C(210,[216],'If H^1(X,C)=0 for every finite abelian coefficient object C in the chosen category, then H^2(X,−) preserves finite limits; its prorepresentability requires a size/accessible-functor condition, and identification with Hom(pi_2,−) is a further theorem.','stated without proof','C','The long exact cohomology sequence proves left exactness. Artin–Mazur develops etale homotopy rather than automatically identifying this unrestricted site-level functor. SGA4 I8.13 gives the categorical pro-object framework; the precise admissible coefficient category on this leaf remains part of the reconstruction.',['SA12_SGA4I','SA12_ArtinMazur1969','SA12_ArtinMazur1967'],'Conference circulation1966/publication1967; monograph1969; SGA4I1972.',comp='Independent long-exact-sequence proof in independent_checks.md §3; no finite computation is advertised as a pi_2 identification.',confidence='medium',batches=(19,21))
C(211,[217],'The map of tame inertia systems induced by a transverse morphism of normal-crossing pairs is governed by local valuation multiplicities; the notation prolongement records extension choices.','proof sketched','A','SGA1 XIII5.3.0 gives the Kummer local model from which the valuation map follows. The source witnesses do not agree on all arrows and coefficient identifications; this match proves the local calculation, not an unqualified global functorial isomorphism.',['SA12_SGA1','SA12_Schmidt2000'],confidence='medium',batches=(3,20))
C(212,[218],'For a square integral multiplicity matrix N, the induced map on prime-to-p Tate lattices is invertible exactly when det N=±p^a; in characteristic0 the determinant must be±1.','proof sketched','A','The arithmetic criterion is the local Kummer calculation applied prime by prime; it also follows immediately from the adjugate formula and reduction modulo a prime divisor. A rectangular matrix needs separate rank and Smith-normal-form conditions.',['SA12_SGA1'],comp='Exact determinants/prime-to-p checks plus universal argument in independent_checks.md §1.',batches=(3,20))
C(213,[221,222],'Over a perfect field a finite group scheme has canonical connected infinitesimal kernel G^0 and finite etale quotient, with reduced subgroup G_red giving G≅G^0⋊G_red.','proof sketched','B','This is part of the standard finite-group-scheme structure used by Nori; the perfectness hypothesis is essential for the reduced subscheme to be a subgroup and for the canonical splitting. Nori1976/1982 develop the resulting pointed finite-group torsor theory. The page does not prove the same split description over arbitrary bases.',['SA12_Nori1976','SA12_Nori1982','SA12_SGA3VIII'],batches=(3,4,7,9))
C(214,[231,260],'For a reduced connected base, geometric-point rigidity of morphisms into infinitesimal finite groups can give uniqueness of pointed torsor morphisms under the page\'s admissibility assumptions; reducedness cannot simply be discarded.','proof sketched','B','The finite torsor theory is established in Nori\'s framework with its hypotheses. On Spec k[epsilon]/epsilon², the alpha_p sections0 and epsilon have the same geometric values but are distinct. This directly isolates the failure when reducedness is dropped. It is not a claim that all morphisms between arbitrary pointed S-schemes are rigid.',['SA12_Nori1976','SA12_Nori1982'],comp='Dual-number computation in exact_checks.json and §3 of independent_checks.md.',batches=(3,4))
C(215,[223,234,235],'A category of admissible finite group objects and pointed torsors, closed under the specified products/equalizers/images, should have minimal pointed torsors and strictly prorepresent the pointed torsor functor; the crucial equalizer must remain a torsor in that category.','proof sketched; gap self-flagged on scans142–143','B','Nori1976 constructs the pointed fundamental group scheme in its reduced connected proper setting, and Nori1982 develops the theory further. The manuscript\'s unrestricted variable-base generalization is false without closure/flatness hypotheses; Antei2015 explains why the category of all finite flat S-groups need not have the fibre products used. The constant-field-group category must not be conflated with the larger S-group category.',['SA12_Nori1976','SA12_Nori1982','SA12_Antei2015'],'Nori1976 publication1976; Nori1982 received1981/published1982; Antei preprint2015.',confidence='medium',batches=(3,4,5,6))
C(216,[224],'For a proper separable morphism with geometrically connected fibres, seek exactness of the homotopy sequence of pointed finite-group torsor groups.','open on the pages','B','Zhang2013 Theorem2.1 supplies an exact criterion under reduced connected locally noetherian perfect-field hypotheses, with irreducible base: every G-saturated torsor must satisfy base change for its pushed-forward algebra and the relevant fibre-group image must be normal. Base change alone is insufficient. This is a precise conditional theorem, not blanket exactness for every proper separable morphism.',['SA12_Zhang2013','SA12_Nori1982'],'Zhang first arXiv2012-06-03, revised2013-07-14.',batches=(3,4,5,6))
C(217,[224],'The stronger hope is that the true finite-group-scheme fundamental groups of the geometric fibres of every smooth proper family form a locally constant system represented by finite flat group schemes over the total space.','open on the pages','A','SGA1 X2.5, originalp271/reprintp208 footnote2, explicitly records an unpublished Artin counterexample already for curves of genus at least2. The exact footnote was visually checked in this run. Pauly2007 supplies a related base-field-extension failure for Nori groups of an ordinary genus2 curve in characteristic2; that later example should not be substituted for the unpublished Artin example.',['SA12_SGA1','SA12_Pauly2007'],'SGA1 publication1971 records an undated unpublished Artin counterexample; Pauly publication2007.',batches=(7,10,11))
C(218,[225],'For pointed proper connected reduced schemes over a perfect field, the finite fundamental group scheme should commute with products.','open on the pages','B','Mehta–Subramanian2002 is the proper full Nori Kunneth theorem (Theorem2.3 as quoted and used by Zhang). Its publisher page was opened but the paywalled proof was not read. Zhang Corollary3.2 proves the local quotient version; §4 refutes the general nonproper version using A1 and a supersingular elliptic curve. These scopes are kept distinct.',['SA12_MehtaSubramanian2002','SA12_Zhang2013'],'Received2001; online2002-01-18; issueApril2002. Zhang first2012/revised2013.',confidence='medium',batches=(3,4,6,10,11))
C(219,[226],'For an abelian variety A with its origin, the pointed finite-group torsor system is dominated by the multiplication torsors [n]:A→A; consequently its fundamental group scheme is lim_n A[n], and its Cartier-dual description uses the direct limit of torsion of the dual abelian variety.','stated without proof','B','Nori1983, opening theorem, explicitly shows that a pointed finite G-torsor is induced from A[n] for some n, over any field. The first-page theorem was opened in primary OCR. The inverse/direct-limit variance and dual variety are essential; this record does not claim the entire paper\'s proof was independently rechecked.',['SA12_Nori1983'],'Received1982-06-07; publishedJune1983.',batches=(4,9))
C(220,[227],'The proposed characteristic-p linearization invokes Witt-type operators and should account for infinitesimal torsors and their variation.','open on the pages','F','Modern Dieudonne theory is a relevant comparator, but the page does not specify the module category, variance, operators or exact family assertion. Searches through Nori, the Grothendieck–Serre correspondence discussion and finite-group literature did not identify one theorem with these quantifiers. The strong family hope is separately refuted in CL-SA12-217; this sketch is not declared a surviving open problem.',['SA12_Nori1982','SA12_Rossler2013','SA12_SGA1'],confidence='low',batches=(4,10,11))
C(221,[229],'For a finite admissible S-group, an infinitesimal kernel with finite etale quotient is unique when it exists.','proof sketched','A','Any map from an infinitesimal S-group to a finite etale S-group lands in the identity section by its clopen inverse image containing every geometric point. Applying this in both directions proves uniqueness. Reducedness of S is unnecessary for this step; it belongs to later rigidity arguments. The connected/etale framework is present in SGA3 and Nori.',['SA12_SGA3VIII','SA12_Nori1976'],comp='Independent universal proof in independent_checks.md §3.',batches=(3,7,9))
C(222,[230],'Descent of the identity/infinitesimal part must be tested after the indicated faithfully flat cover, rather than by the earlier deleted shortcut.','corrected by himself later: deleted shortcut on scan137 and replacement on same scan','A','Fpqc descent of affine schemes and group morphisms supplies the corrected mechanism; SGA1 VIII and SGA3 VIII are exact formalism comparators. The deletion is not attributed to a specific mathematical objection beyond what the page states.',['SA12_SGA1','SA12_SGA3VIII'],batches=(3,7,9))
C(223,[234,236],'The equalizer of two maps of finite flat S-groups need not be finite flat. In characteristicp, Eq(0,[t]:alpha_p→alpha_p) over k[t] has generic length1 and special lengthp.','false as an unrestricted inference; counterexample supplied by earlier run','B','Antei2015 §2 explains the absence of fibre products in the unrestricted finite-flat category. The explicit equalizer A[T]/(T^p,tT) proves the relevant obstruction. It does not refute a manuscript axiom that expressly restricts to categories closed under those kernels.',['SA12_Antei2015'],comp='Fibre-length calculation in exact_checks.json and independent_checks.md §3.',batches=(4,6))
C(224,[234,237],'Minimality of a pointed finite flat torsor over a reduced connected base does not by itself make Hom(G,G′)→H^1_pointed(S,G′) injective for all S-group maps.','false as an unrestricted assertion; restricted constant-group statement not refuted','C','On the reduced cusp S=Spec k[w^p,w^{p+1}], the nontrivial pointed alpha_p torsor z^p=x is minimal, while0 and[x] have pointed-trivial pushforwards. Their coincidence reduction is the nonflat normalization. Every stated hypothesis of this unrestricted version is checked in §4. The morphism[x] varies with the base, so the example does not lie in the constant k-group morphism category.',['SA12_Nori1976','SA12_Antei2015'],comp='Exact cusp normalization/fibre checks for p=2,3,5,7; universal semigroup and flatness argument in independent_checks.md §4.',batches=(3,4,6))
C(225,[240],'For ideals J,J′, comaximality implies J∩J′=JJ′ and the product quotient decomposition; equality of intersection and product alone does not imply comaximality.','proof sketched; converse reading false','E','The forward statement is the Chinese remainder theorem, verified in Stacks00DT Lemma10.15.4. Ideals(x),(y) in k[x,y] give equality(xy) but sum(x,y)≠1. Scan108 may presuppose extra monic-factor hypotheses; the bare converse is what fails.',['SA12_Stacks00DT'],comp='Groebner elimination for the intersection in exact_checks.json and the universal proof in §5.',batches=(22,25))
C(226,[241,242],'If A is connected, J+J′=A[T] and JJ′=(P) with P monic, then J and J′ have unique monic generators Q,Q′ with P=QQ′.','proof sketched; written argument stops on scan111','E','CRT and finite-projective module theory give a complete proof: the two quotient factors have constant ranks, characteristic polynomials of multiplication by T generate the two ideals, and block determinants multiply to P. Stacks00DT and00NV verify the two standard inputs. This does not claim an exact historical printing of the fragment was located.',['SA12_Stacks00DT','SA12_Stacks00NV'],comp='Independent full Cayley–Hamilton proof §5 plus exact block-characteristic-polynomial check. Disconnected-base counterexample supplied.',batches=(22,25))
C(227,[243,244],'The representability test on scan133 seeks an etale scheme from a functor with sheaf, field-extension, locality and limit properties; the exact full criterion is unfinished.','stated without proof','C','SGA3 XI3.1 and3.5 give precise open-immersion and gluing representability criteria, including fpqc sheaf, filtered-limit and adic-effectivity conditions plus infinitesimal etaleness. They demonstrate which omitted hypotheses matter, but are not an exact match to every draft condition on scan133. Testing only separable extensions cannot replace algebraically closed field tests without further assumptions.',['SA12_SGA3XI'],'SGA3 seminar1962–64; publication1970; Polo corrected edition2009.',confidence='medium',batches=(7,13,14,23))
C(228,[245],'Compatible etale schemes over the local rings of a scheme should glue when the data extend to neighborhoods with the required overlap compatibility.','proof sketched','A','SGA3 XI3.5 explicitly constructs the scheme by gluing open representable subfunctors. Compatibility only over local schemes is insufficient: the local data in §6 would give image{generic point,c}⊂A1, which is not open. The source\'s inserted neighborhood condition is therefore substantive.',['SA12_SGA3XI'],comp='Independent topological image counterexample with all local models specified in independent_checks.md §6.',batches=(13,14,23))
C(229,[246,253,254],'The relative pointed-torsor functor F_G and the center-valued functor Z(G) vary in different arguments; its claimed finiteness/representability must retain the relative-base hypotheses and the separately inserted universal O-coherence condition.','stated without proof','C','Nori and later relative fundamental-group-scheme work develop such torsor functors under controlled bases; Antei2015 shows why all finite flat S-groups are not automatically a valid filtered system. SGA3 XI3.12 is representability for multiplicative-type Hom/subgroup functors, not a theorem about this arbitrary pointed-torsor functor. The exact scan131 formulation remains unmatched.',['SA12_Nori1982','SA12_Antei2015','SA12_SGA3XI'],confidence='medium',batches=(4,7,13,14))
C(230,[247],'A morphism of locally diagonalizable groups over S has locally diagonalizable kernel; when the target is of finite type, its quotient by the kernel is locally diagonalizable and maps as a closed subgroup of the target.','proved there, with inserted finite-type hypothesis','A','The wording and inserted condition match SGA3 VIII Corollary3.4. Under character duality u:N→M, kernel corresponds to coker(u), quotient to im(u), and the closed immersion follows from the character quotient. The finite-type insertion is retained.',['SA12_SGA3VIII'],'Published1970; corrected edition2009 opened.',batches=(7,9))
C(231,[247],'An injective homomorphism of character groups induces a faithfully flat quasi-compact map of diagonalizable groups; its kernel is dual to the character cokernel. Conversely the group-scheme assertion detects injectivity when S is nonempty.','proved there','A','Exact match SGA3 VIII3.2–3.3; the group-algebra basis of coset representatives proves faithful flatness. Empty S is excluded only for converse deductions about the underlying abstract groups.',['SA12_SGA3VIII'],comp='Independent group-algebra proof also recorded by review29a §6.',batches=(7,9))
C(232,[247],'The diagonalizable quotient construction and the subgroup classification are local for fpqc and extend through descent to locally diagonalizable groups.','proved there','A','Matched to SGA3 VIII3.5 and§4, with the finite-type clauses stated there. Modern terminology of multiplicative type is a comparison label, not substituted ink.',['SA12_SGA3VIII'],batches=(7,9))
C(233,[250],'The unramified-morphism characterization numbered17.4.10 is used with its finite-presentation/residue-field hypotheses; the smooth characterization17.5.1 needs flatness in addition to smooth geometric fibres and the finite-presentation conditions.','stated with proof/reference on reused EGA sheet','A','The page is explicitly an EGA IV17.4.10/17.5.1 typescript fragment. EGA IV4(1967) is its exact published home, not an inference from a broad smoothness theorem. All equivalences must be read with the local finiteness assumptions; this run does not attribute the reused typescript\'s authorship beyond the source.',['SA12_EGAIV4'],'Publication1967.',confidence='medium',batches=(12,13,14))
C(234,[249],'For a finite-dimensional K-subspace W⊂K^n, the field generated by ratios of nonzero Plucker coordinates is its smallest field of definition inside K.','proof sketched on reused English typescript','E','The graph-coordinate/Gaussian-elimination argument is independently verified in §10. Exact-title searches for the English fragment did not identify its author or publication; mathematical standardness is distinct from bibliographic identification. The arbitrary-dimensional or arbitrary-intermediate-field extension must retain the specified rational structures.',['SA12_SGA1'],comp='Independent chart argument in §10; no historical author attribution.',confidence='medium',batches=(15,16))
C(235,[249],'A multilinear map between spaces endowed with rational structures is rational precisely when its coefficients in finite rational bases lie in the ground field; images and inverse images of rational subspaces are rational.','proved/sketched on reused English typescript','E','The finite-basis coefficient argument is standard linear algebra and independently re-proved here. Exact searches for the fragment\'s title and its linear/multilinear wording gave no primary attribution. This is not assigned to Grothendieck merely because it survives among his sheets.',['SA12_SGA1'],comp='§10 proof and explicit graph-sign counterexample in exact_checks.json. The graph equation requires a minus sign.',confidence='medium',batches=(15,16))
C(236,[255],'For Z=Spec C[[x,y]], the ordinary etale fundamental group is trivial; the prime-to-characteristic two-inertia lattice belongs to the complement of a normal-crossing boundary, not to the strictly henselian local scheme itself.','displayed notation ambiguous; literal unpunctured interpretation false','A','The finite-etale theory of strictly henselian local schemes gives the trivial group; SGA1 XIII5.3.0 computes the normal-crossing complement by two Kummer directions. The possible omitted complement is a scan question, not an adopted correction.',['SA12_SGA1'],batches=(3,20))
C(237,[256],'Earlier-run comparison: the root stack of a divisor and the gerbe of roots of a line bundle are different objects; their relationship to tame covering constructions needs separate specification.','not an authorial claim; earlier-run comparison','B','Stacks04V8 describes root stacks with stabilizers along the divisor. For [A1_z/mu_n], t=z^n, stabilizers vanish off0; for Bmu_n×A1 they are present everywhere. This rejects an identification in commentary while retaining the useful finite-Kummer link.',['SA12_Stacks04V8','SA12_Stacks03PK'],comp='Independent stabilizer calculation in §10.',batches=(3,4))
C(238,[257],'Kummer root torsors are available in the fppf topology for every positive n and in the etale topology when n is invertible.','not a distinct authorial theorem; topology check of earlier-run bridge','A','Stacks03PK explicitly states the fppf and invertible-etale Kummer sequences. The algebra A[z]/(z^n−a), a a unit, is finite free faithfully flat; invertibility of nz^(n−1) gives etaleness when n is invertible. This does not extend etale Kummer theory to n=p in characteristicp.',['SA12_Stacks03PK'],comp='Universal algebra check in §10.',batches=(3,4))

# Codex-only continuations, read directly; they do not create indexed verdict rows.
def E(n,scans,file,lines,words,statement,kind='unproved claim',reason='The Codex lead was checked against the entire indicated passage. No Pro indexed entry covers this continuation.'):
    i=dict(id=f'SA12-{n}',sources=['codex/'+file+'_notes.md'],kind=kind,cote='29',scans=scans,lines=file+'_transcription.tex:'+lines,his_words=words,statement=statement,reconstruction='Any modern formulation and attribution limits are stated in the associated claim records. This item adds a Codex-only source passage, not a synthetic NOTES_INDEX row.',check='agrees',check_reason=reason);items.append(i);by[i['id']]=i
